<?php
declare(strict_types=1);
require_once __DIR__.'/helpers.php';

function active_cart(string $userId,bool $forUpdate=false): array {
    $db=get_db();$sql='SELECT * FROM carts WHERE user_id=:user AND status="active" LIMIT 1'.($forUpdate?' FOR UPDATE':'');$stmt=$db->prepare($sql);$stmt->execute(['user'=>$userId]);$cart=$stmt->fetch();
    if(!$cart){$id=uuid_string();$db->prepare('INSERT INTO carts (id,user_id,status,currency,created_at,updated_at) VALUES (:id,:user,"active","INR",UTC_TIMESTAMP(),UTC_TIMESTAMP())')->execute(['id'=>$id,'user'=>$userId]);$cart=['id'=>$id,'user_id'=>$userId,'status'=>'active','currency'=>'INR'];}
    return $cart;
}
function cart_details(string $userId): array {
    $cart=active_cart($userId);$stmt=get_db()->prepare('SELECT ci.id,ci.variant_id,ci.quantity,p.id AS product_id,p.vendor_id,p.name,p.slug,p.sku,p.mrp,p.selling_price,p.gst_percent,p.package_weight_grams,p.processing_min_days,p.processing_max_days,p.status,pv.name AS variant_name,pv.sku AS variant_sku,pv.price_adjustment,i.stock_quantity,i.reserved_quantity,(i.stock_quantity-i.reserved_quantity) AS available_quantity,v.display_name AS vendor_name,(SELECT CONCAT("../files.php?id=",f.id) FROM product_images pi JOIN file_assets f ON f.id=pi.file_asset_id WHERE pi.product_id=p.id AND f.visibility="public" AND f.scan_status="clean" AND f.deleted_at IS NULL ORDER BY pi.is_primary DESC,pi.sort_order LIMIT 1) AS image_url FROM cart_items ci JOIN product_variants pv ON pv.id=ci.variant_id JOIN products p ON p.id=pv.product_id JOIN vendors v ON v.id=p.vendor_id JOIN inventory_levels i ON i.variant_id=pv.id WHERE ci.cart_id=:cart ORDER BY ci.created_at');$stmt->execute(['cart'=>$cart['id']]);$items=$stmt->fetchAll();$subtotal=0.0;foreach($items as &$item){$item['unit_price']=round((float)$item['selling_price']+(float)$item['price_adjustment'],2);$item['line_subtotal']=round($item['unit_price']*(int)$item['quantity'],2);$subtotal+=$item['line_subtotal'];}$cart['items']=$items;$cart['subtotal']=round($subtotal,2);$cart['item_count']=array_sum(array_map(fn($i)=>(int)$i['quantity'],$items));return $cart;
}
function shipping_for_vendor(string $vendorId,array $address,float $orderValue,int $weightGrams): array {
    $db=get_db();$stmt=$db->prepare('SELECT * FROM vendor_shipping_settings WHERE vendor_id=:vendor');$stmt->execute(['vendor'=>$vendorId]);$settings=$stmt->fetch();if(!$settings)return ['serviceable'=>false,'amount'=>0.0,'reason'=>'Vendor delivery settings are incomplete.','rule'=>null];
    $zones=$db->prepare('SELECT * FROM vendor_shipping_zones WHERE vendor_id=:vendor AND is_active=1 ORDER BY is_exclusion DESC,CASE rule_type WHEN "pincode" THEN 1 WHEN "city" THEN 2 WHEN "state" THEN 3 ELSE 4 END');$zones->execute(['vendor'=>$vendorId]);$matched=null;$excluded=false;
    foreach($zones->fetchAll() as $zone){$match=false;if($zone['rule_type']==='all_india')$match=true;elseif($zone['rule_type']==='state')$match=strcasecmp((string)$zone['state'],(string)$address['state'])===0;elseif($zone['rule_type']==='city')$match=strcasecmp((string)$zone['state'],(string)$address['state'])===0&&strcasecmp((string)$zone['city'],(string)$address['city'])===0;elseif($zone['rule_type']==='pincode')$match=(string)$address['pincode']>=(string)$zone['pincode_from']&&(string)$address['pincode']<=(string)$zone['pincode_to'];if($match){if((int)$zone['is_exclusion']===1){$excluded=true;break;}if($matched===null)$matched=$zone;}}
    if($excluded)return ['serviceable'=>false,'amount'=>0.0,'reason'=>'This delivery location is excluded by the vendor.','rule'=>['coverage'=>'excluded']];
    $coverage=(string)$settings['coverage_model'];if($matched===null&&$coverage!=='all_india')return ['serviceable'=>false,'amount'=>0.0,'reason'=>'The vendor does not currently deliver to this location.','rule'=>null];
    if($settings['free_above']!==null&&$orderValue>=(float)$settings['free_above'])return ['serviceable'=>true,'amount'=>0.0,'reason'=>null,'rule'=>['type'=>'free_above','threshold'=>(float)$settings['free_above'],'zone_id'=>$matched['id']??null]];
    $sql='SELECT * FROM vendor_shipping_rates WHERE vendor_id=:vendor AND is_active=1 AND (zone_id=:zone OR zone_id IS NULL) AND (min_weight_grams IS NULL OR min_weight_grams<=:min_weight) AND (max_weight_grams IS NULL OR max_weight_grams>=:max_weight) AND (min_order_value IS NULL OR min_order_value<=:min_value) AND (max_order_value IS NULL OR max_order_value>=:max_value) ORDER BY (zone_id IS NOT NULL) DESC,id LIMIT 1';$rate=$db->prepare($sql);$rate->execute(['vendor'=>$vendorId,'zone'=>$matched['id']??'','min_weight'=>$weightGrams,'max_weight'=>$weightGrams,'min_value'=>$orderValue,'max_value'=>$orderValue]);$row=$rate->fetch();$amount=$row?(float)$row['charge']:(float)$settings['base_charge'];return ['serviceable'=>true,'amount'=>round(max(0,$amount),2),'reason'=>null,'rule'=>['type'=>$row['calculation_type']??'flat','rate_id'=>$row['id']??null,'zone_id'=>$matched['id']??null,'coverage'=>$coverage]];
}
function release_quote_reservations(string $quoteId): void {
    $db=get_db();$stmt=$db->prepare('SELECT * FROM inventory_reservations WHERE quote_id=:quote AND status="reserved" FOR UPDATE');$stmt->execute(['quote'=>$quoteId]);foreach($stmt->fetchAll() as $reservation){$db->prepare('UPDATE inventory_levels SET reserved_quantity=reserved_quantity-:qty_decrease,updated_at=UTC_TIMESTAMP() WHERE variant_id=:variant AND reserved_quantity>=:qty_guard')->execute(['qty_decrease'=>$reservation['quantity'],'qty_guard'=>$reservation['quantity'],'variant'=>$reservation['variant_id']]);$db->prepare('UPDATE inventory_reservations SET status="released",released_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$reservation['id']]);}
}
function order_number(): string {return 'CI-'.gmdate('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8));}

function attribute_influencer_order(int $orderId,string $userId,float $orderAmount): ?string {
    $clickId=trim((string)($_COOKIE['ci_referral_click']??''));if($clickId==='')return null;$db=get_db();$stmt=$db->prepare('SELECT c.id click_id,c.clicked_at,l.influencer_id,l.campaign_id,ic.commission_type,ic.commission_value,ic.attribution_days,i.email influencer_email,u.email customer_email FROM referral_clicks c JOIN influencer_referral_links l ON l.id=c.referral_link_id JOIN influencer_campaigns ic ON ic.id=l.campaign_id JOIN influencers i ON i.id=l.influencer_id JOIN users u ON u.id=:user WHERE c.id=:click AND l.status="active" AND ic.status="active" AND i.status="active" AND ic.starts_at<=UTC_TIMESTAMP() AND ic.ends_at>=UTC_TIMESTAMP()');$stmt->execute(['user'=>$userId,'click'=>$clickId]);$referral=$stmt->fetch();if(!$referral||strtotime($referral['clicked_at'])<time()-86400*(int)$referral['attribution_days'])return null;$fraud=[];if(strcasecmp($referral['influencer_email'],$referral['customer_email'])===0)$fraud[]='self_referral';$commission=$referral['commission_type']==='percent'?round($orderAmount*(float)$referral['commission_value']/100,2):round((float)$referral['commission_value'],2);$status=$fraud?'flagged':'pending';$id=uuid_string();try{$db->prepare('INSERT INTO influencer_conversions (id,influencer_id,campaign_id,click_id,order_id,order_amount,commission_amount,status,fraud_flags_json,created_at,eligible_at) VALUES (:id,:owner,:campaign,:click,:order,:amount,:commission,:status,:fraud,UTC_TIMESTAMP(),DATE_ADD(UTC_TIMESTAMP(),INTERVAL 7 DAY))')->execute(['id'=>$id,'owner'=>$referral['influencer_id'],'campaign'=>$referral['campaign_id'],'click'=>$clickId,'order'=>$orderId,'amount'=>$orderAmount,'commission'=>$commission,'status'=>$status,'fraud'=>$fraud?json_encode($fraud):null]);$db->prepare('INSERT INTO influencer_ledger_entries (id,influencer_id,entry_type,amount,status,reference_type,reference_id,created_at) VALUES (:id,:owner,"commission",:amount,:status,"conversion",:reference,UTC_TIMESTAMP())')->execute(['id'=>uuid_string(),'owner'=>$referral['influencer_id'],'amount'=>$commission,'status'=>$status,'reference'=>$id]);return $id;}catch(PDOException $e){if((string)$e->getCode()==='23000')return null;throw $e;}
}
